css:
.button {
  cursor: pointer;
  font-size: large;
  font-family: inherit;
  font-weight: bold;
  color: #ffaf02;
  background-color: #ffffe3;
  padding: 0.8em 1.8em;
  border-radius: 50em;
  border: 6px solid rgb(247, 169, 133);
  box-shadow: 0px 8px #f32b11;
}
.button:active {
  position: relative;
  top: 8px;
  border: 6px solid #ffb764;
  box-shadow: 0px 0px;
}
